// 只读对照：单个已知资产的标准库规范化与对应 Win32 调用；不是等价替代实现。
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>
#include <cstdint>
std::uint64_t cpu() {
 FILETIME a{},b{},k{},u{};
 if (!GetThreadTimes(GetCurrentThread(), &a,&b,&k,&u)) return 0;
 auto ticks=[](FILETIME x){return (static_cast<std::uint64_t>(x.dwHighDateTime)<<32)|x.dwLowDateTime;};
 return ticks(k)+ticks(u);
}
int main(int argc,char** argv) {
 if(argc!=3)return 2;
 std::u8string utf8;
 for (const char c: std::string_view(argv[1])) utf8.push_back(static_cast<char8_t>(c));
 const std::filesystem::path path(utf8);
 std::ofstream out(argv[2]);out<<"iteration,operation,wall_ms,thread_cpu_ms,error\n";
 auto sample=[&](int i,const char* name,auto&& fn){
  const auto c=cpu();const auto t=std::chrono::steady_clock::now();
  const auto error=fn();
  const auto wall=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();
  const auto used=static_cast<double>(cpu()-c)/10000.0;
  out<<i<<','<<name<<','<<wall<<','<<used<<','<<error<<'\n';out.flush();return error;
 };
 for(int i=0;i<64;++i){
  if(sample(i,"canonical",[&]{std::error_code ec;const auto p=std::filesystem::canonical(path,ec);return ec.value();}))return 3;
  HANDLE h=INVALID_HANDLE_VALUE;
  if(sample(i,"CreateFileW",[&]{h=CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr);return h==INVALID_HANDLE_VALUE?GetLastError():0UL;}))return 4;
  std::vector<wchar_t> buffer(32768);
  const auto queried=sample(i,"GetFinalPathNameByHandleW",[&]{const auto n=GetFinalPathNameByHandleW(h,buffer.data(),static_cast<DWORD>(buffer.size()),VOLUME_NAME_DOS|FILE_NAME_NORMALIZED);return n==0?GetLastError():n>=buffer.size()?ERROR_INSUFFICIENT_BUFFER:0UL;});
  const auto closed=sample(i,"CloseHandle",[&]{return CloseHandle(h)?0UL:GetLastError();});
  if(queried||closed)return 5;
  Sleep(10);
 }
 return out?0:6;
}
